OrbitTrapMasterController.Instructions:
comment:
  
  Blends the colors returned by controller 0 and 
  controller 1 based on a fixed value or a blending
  curve defined by a sample point value.
  
color:
  
  if (VariableBlend) {
    r = Blend
    
    if (Power <> 1) {
      r = r^Power
    }
    if (Factor <> 1 || Offset <> 0) {
      r = Clip(Offset + Factor*r)
    }
    if (Invert) {
      r = 1-r
    }
  } else {
    r = BlendPower
  }
  color = Color.Blend( \
    ColorBlendType, \
    Controller.Color(0), \
    Controller.Color(1), \
    r \
  )
  
properties:
  
#include ColorBlendTypes

  divider {
    caption = "Color Blend Options"
  }
  option ColorBlendType {
    type = ColorBlendTypes
    caption = "Blend Type"
    details = "Type of blend"
    default = ColorBlendTypes.SoftLight
  }
  option VariableBlend {
    type = Boolean
    caption = "Variable Blend"
    details = "Blend strength defined by blending curve"
    default = True
  }
  divider {
    caption = "Constant Blend"
    enabled = ~VariableBlend
  }
  option BlendPower {
    type = Float
    caption = "Power"
    details = "Power applied to blend (0-1)"
    default = 1
    range = [0,1]
    enabled = ~VariableBlend
  }
  divider {
    caption = "Variable Blend"
    enabled = VariableBlend
  }
  option Blend {
    type = SamplePointValue
    caption = "Blend"
    default = Sample.TrapDwell
    enabled = VariableBlend
  }
  option Power {
    type = Float
    caption = "Power"
    details = "Alters shape of blending curve (> 0)"
    default = 0.5
    range = (0,)
    enabled = VariableBlend
  }
  option Factor {
    type = Float
    caption = "Factor"
    details = "Alters shape of blending curve (> 0)"
    default = 1
    range = (0,)
    enabled = VariableBlend
  }
  option Offset {
    type = Float
    caption = "Offset"
    details = "Alters position of blending curve"
    default = 0
    enabled = VariableBlend
  }
  option Invert {
    type = Boolean
    caption = "Invert"
    details = "Inverts blending curve"
    default = True
    enabled = VariableBlend
  }
